tool_uses.input:
{"query": "WITH base AS (
  SELECT DISTINCT Gene, "Protein class" AS pc, "RNA tissue specificity" AS spec, "RNA tissue specific nTPM" AS nt
  FROM proteinatlas
),
c2 AS (SELECT DISTINCT Gene FROM base WHERE pc LIKE '%Transporters%' AND spec='Tissue enriched' AND nt LIKE 'kidney:%')
SELECT Gene FROM c2 ORDER BY Gene"}

{"query": "SELECT COUNT(*) AS genes_both_tissues FROM (
  SELECT Gene, COUNT(DISTINCT Tissue) t
  FROM rna_tissue_consensus WHERE Tissue IN ('pancreas','kidney')
  GROUP BY Gene HAVING COUNT(DISTINCT Tissue)=2
)"}

input.query:
SELECT COUNT(*) AS dup_pairs FROM (
  SELECT Gene, Tissue, COUNT(*) c FROM rna_tissue_consensus GROUP BY Gene, Tissue HAVING COUNT(*)>1
)
